<script lang="ts">
 import {upcoming,schedules,scheduleAction,formatMoney,formatDate,type UpcomingItem,type ScheduleView,type AccountOverview} from './lib/api'; import ScheduleSheet from './ScheduleSheet.svelte';
 let {version,accounts,refresh}:{version:string;accounts:AccountOverview[];refresh:()=>void}=$props();
 let items=$state<UpcomingItem[]>([]), list=$state<ScheduleView[]>([]), error=$state(''), local=$state(0), sheet=$state(false); let request=0;
 $effect(()=>{void version;void local;const id=++request;void Promise.all([upcoming(),schedules()]).then(([i,s])=>{if(id===request){items=i;list=s;}}).catch(e=>error=String(e));});
 let overdue=$derived(items.filter(i=>i.overdue)), coming=$derived(items.filter(i=>!i.overdue));
 let sections = $derived([{title:'Vencidos', rows:overdue}, {title:'Próximos 30 días', rows:coming}]);
 function updated(){local++;refresh();} async function action(id:number,act:string){try{await scheduleAction(id,act);updated();}catch(e){error=String(e);}}
 function key(e:KeyboardEvent){if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='n'){e.preventDefault();sheet=true;}}
</script>
<svelte:window onkeydown={key}/><div class="screen"><header><div><h1>Tus próximos compromisos</h1><p>Anticipa tus pagos y cuida tu saldo</p></div><button onclick={()=>sheet=true}>Nuevo pago programado</button></header>
{#if error}<p class="error" role="alert">{error}</p>{/if}<div class="metrics"><section><h2>Vencidos</h2><strong class:amber={overdue.length>0}>{overdue.length}</strong></section><section><h2>Próximos 30 días</h2><strong>{coming.length}</strong></section><section><h2>Pagos programados</h2><strong>{list.length}</strong></section></div>
{#each sections as section}{#if section.title !== 'Vencidos' || section.rows.length}<section class="card"><h2>{section.title}</h2>{#each section.rows as item (item.scheduleId + '-' + item.date)}{@const schedule=list.find(s=>s.schedule.id===item.scheduleId)}<div class="item"><div class:amber={item.overdue} class="date">{formatDate(item.date)}{#if item.overdue}<small>Vencido</small>{/if}</div><div><strong>{item.name}</strong><small>{[schedule?.payee,item.account].filter(Boolean).join(' · ')}</small></div><div class="amount" class:expense={item.amount<0} class:income={item.amount>=0}><strong>{formatMoney(item.amount)}</strong>{#if item.projectedBalance!==null}<small class:expense={item.projectedBalance<0}>Saldo: {formatMoney(item.projectedBalance)}</small>{/if}{#if schedule?.nextDate===item.date}<div><button onclick={()=>action(item.scheduleId,'post')}>Registrar</button><button onclick={()=>action(item.scheduleId,'skip')}>Saltar</button></div>{/if}</div></div>{:else}<p>Nada programado</p>{/each}</section>{/if}{/each}
<section class="card"><h2>Pagos programados</h2>{#each list as s (s.schedule.id)}<div class="item" role="group" oncontextmenu={e => {e.preventDefault(); const menu=e.currentTarget.querySelector('details'); if(menu) menu.open=true;}}><div><strong>{s.schedule.name}</strong><small>{s.label.replace(/(\d{2})\.(\d{2})\.(\d{4})/, '$1/$2/$3')}</small></div><span class:expense={s.schedule.amount<0} class:income={s.schedule.amount>=0}>{formatMoney(s.schedule.amount)}</span><details><summary aria-label={`Acciones de ${s.schedule.name}`}>⋯</summary><button onclick={()=>action(s.schedule.id,'delete')}>Eliminar</button></details></div>{/each}</section></div>
{#if sheet}<ScheduleSheet {accounts} close={()=>sheet=false} saved={()=>{sheet=false;updated();}}/>{/if}
<style>.screen{display:grid;gap:18px;max-width:1500px;margin:auto}header,.item{display:flex;justify-content:space-between;align-items:center;gap:16px}h1,h2,p{margin:0}h2{font-size:1rem;margin-bottom:12px}p,small{color:var(--muted)}small{display:block;font-size:.8rem}.metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:16px}.metrics section,.card{background:var(--card);border:1px solid var(--border);border-radius:18px;padding:20px}.metrics strong{font-size:1.6rem}.item{padding:14px 0;border-bottom:1px solid var(--border)}.item>div:nth-child(2){flex:1}.amount{text-align:right}.date{background:var(--canvas);border-radius:8px;padding:10px;white-space:nowrap}.amber{color:var(--amber)}.expense,.error{color:var(--coral)}.income{color:var(--emerald)}button{font:inherit;background:var(--canvas);color:inherit;border:1px solid var(--border);border-radius:8px;padding:7px;cursor:pointer}summary{cursor:pointer}</style>
